-- INSERT INTO orders VALUES(3,'kim',5000),(4,'lee',2000);
-- INSERT INTO orders VALUES(5,'park',700);
WITH ranked AS (
  SELECT id, customer, amount,
    ROW_NUMBER() OVER (ORDER BY amount DESC) AS rn
  FROM orders
)
SELECT id FROM ranked
WHERE rn = 1
ORDER BY id;

